import { isValidDate, deLocalizeDate, translate, localizeDate } from '@ps-refarch-ux/mfe-utils';
export function validateIsDate(input, condition, context) {
    //console.log('validating isDate');
    const result = {
        isValid: isValidDate(input)
    };
    if (result.isValid) {
        context.parsedDate = deLocalizeDate(input);
    }
    else {
        result.errorMessage = translate('neon|validation engine|Must be a date');
    }
    //console.log('result: ' + result.isValid);
    return result;
}
export function validateMaxDate(input, maxDate, context) {
    //console.log('validating maxDate');
    const result = {
        isValid: context.parsedDate.getTime() <= maxDate.getTime()
    };
    if (!result.isValid) {
        result.errorMessage = translate('neon|validation engine|The date must be on or before xx', { maxDate: localizeDate(maxDate) });
    }
    //console.log('result: ' + result.isValid);
    return result;
}
export function validateMinDate(input, minDate, context) {
    //console.log('validating minDate');
    const result = {
        isValid: context.parsedDate.getTime() >= minDate.getTime()
    };
    if (!result.isValid) {
        result.errorMessage = translate('neon|validation engine|The date must be on or after xx', { minDate: localizeDate(minDate) });
    }
    //console.log('result: ' + result.isValid);
    return result;
}
export function validateWeekdaysOnly(input, condition, context) {
    //console.log('validating weekdaysOnly');
    const result = {
        isValid: context.parsedDate.getDay() !== 0 && context.parsedDate.getDay() !== 6
    };
    if (!result.isValid) {
        result.errorMessage = translate('neon|validation engine|Must be a weekday');
    }
    //console.log('result: ' + result.isValid);
    return result;
}
